// Chapter 11 demo: ROC curve + threshold slider -> live confusion matrix.
// Data: window.CH11_ROC_DATA (from ch11-roc-data.js, generated by scripts/figs_ch11.py).
// Rule: predicted positive when score >= threshold (same as the Python check).
function initCh11Roc() {
  const el = document.getElementById("ch11-demo");
  if (!el) return;
  const data = window.CH11_ROC_DATA;
  if (!data || !window.Plotly) {
    el.textContent = "互動資料載入失敗，請重新整理頁面。";
    return;
  }
  const slider = document.getElementById("ch11-thr");
  const thrOut = document.getElementById("ch11-thr-val");
  const table = document.getElementById("ch11-cm");
  const score = data.score, label = data.label, n = score.length;

  function confusion(t) {
    let tp = 0, fp = 0, fn = 0, tn = 0;
    for (let i = 0; i < n; i++) {
      const pos = score[i] >= t;
      if (label[i] === 1) { if (pos) tp++; else fn++; }
      else { if (pos) fp++; else tn++; }
    }
    return { tp, fp, fn, tn };
  }

  // ROC points at every distinct score (plus the two ends)
  const cuts = Array.from(new Set(score)).sort((a, b) => b - a);
  const P = label.reduce((s, v) => s + v, 0), N = n - P;
  const rocX = [0], rocY = [0];
  cuts.forEach((c) => {
    const m = confusion(c);
    rocX.push(m.fp / N);
    rocY.push(m.tp / P);
  });
  rocX.push(1); rocY.push(1);
  let auc = 0;
  for (let i = 1; i < rocX.length; i++) auc += (rocX[i] - rocX[i - 1]) * (rocY[i] + rocY[i - 1]) / 2;

  const pct = (a, b) => (b ? (100 * a / b).toFixed(1) + "%" : "—");

  function colors() {
    const s = getComputedStyle(document.body);
    return {
      fg: s.getPropertyValue("--md-default-fg-color").trim() || "#333",
      grid: s.getPropertyValue("--md-default-fg-color--lightest").trim() || "#ddd",
    };
  }

  function draw() {
    const t = parseFloat(slider.value);
    thrOut.textContent = t.toFixed(2);
    const m = confusion(t);
    const sens = m.tp / P, spec = m.tn / N;
    const c = colors();
    const traces = [
      { x: rocX, y: rocY, mode: "lines", name: "ROC（AUC " + auc.toFixed(3) + "）",
        line: { color: "#00897B", width: 3 } },
      { x: [0, 1], y: [0, 1], mode: "lines", name: "亂猜", line: { color: "#607D8B", dash: "dash" } },
      { x: [1 - spec], y: [sens], mode: "markers", name: "目前閾值",
        marker: { color: "#F4511E", size: 14 } },
    ];
    const layout = {
      margin: { l: 55, r: 10, t: 10, b: 50 }, height: 380,
      paper_bgcolor: "rgba(0,0,0,0)", plot_bgcolor: "rgba(0,0,0,0)",
      font: { color: c.fg },
      xaxis: { title: "1 − 特異度（偽陽性率）", range: [0, 1], gridcolor: c.grid, zeroline: false },
      yaxis: { title: "敏感度（真陽性率）", range: [0, 1.02], gridcolor: c.grid, zeroline: false },
      legend: { x: 0.45, y: 0.1, bgcolor: "rgba(0,0,0,0)" },
    };
    Plotly.react(el, traces, layout, { displayModeBar: false, responsive: true });
    table.innerHTML =
      "<table><thead><tr><th></th><th>真的有糖尿病</th><th>真的沒有</th></tr></thead><tbody>" +
      "<tr><th>模型判陽性</th><td>TP " + m.tp + "</td><td>FP " + m.fp + "</td></tr>" +
      "<tr><th>模型判陰性</th><td>FN " + m.fn + "</td><td>TN " + m.tn + "</td></tr></tbody></table>" +
      "<p>敏感度 <b>" + pct(m.tp, P) + "</b> ・ 特異度 <b>" + pct(m.tn, N) +
      "</b> ・ PPV <b>" + pct(m.tp, m.tp + m.fp) + "</b> ・ NPV <b>" + pct(m.tn, m.tn + m.fn) +
      "</b> ・ 準確率 <b>" + pct(m.tp + m.tn, n) + "</b>（測試集 " + n + " 人，陽性 " + P + " 人）</p>";
  }

  slider.addEventListener("input", draw);
  // Redraw when the user toggles light/dark mode
  const obs = new MutationObserver(draw);
  obs.observe(document.body, { attributes: true, attributeFilter: ["data-md-color-scheme"] });
  draw();
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initCh11Roc);
else initCh11Roc();
